class dtNavMesh
{
public:
	dtNavMesh();
	~dtNavMesh();
	dtStatus init(const dtNavMeshParams* params);
	dtStatus init(unsigned char* data, const int dataSize, const int flags);
	const dtNavMeshParams* getParams() const;
